package com.cestasdamel.erp.repository; import com.cestasdamel.erp.model.Purchase; import org.springframework.data.jpa.repository.*; import java.time.Instant; import java.math.BigDecimal; import java.util.*;
public interface PurchaseRepository extends JpaRepository<Purchase,Long>{ @EntityGraph(attributePaths="items") List<Purchase> findAllByOrderByPurchasedAtDesc(); @Query("select coalesce(sum(p.total),0) from Purchase p where p.purchasedAt>=:from and p.purchasedAt<:to") BigDecimal sumBetween(Instant from,Instant to); boolean existsByReceiptAccessKey(String receiptAccessKey); }
